type EventItem = { id: number; organizerId?: string | null; title: string; category: string; city: string; venue: string; date: string; time: string; price: number; sold: number; capacity: number; image: string; description: string; featured?: boolean; preview?: boolean }
type EventDraft = { title: string; city: string; date: string; venue: string; price: number }
type TicketItem = { id: string; recordId: string; attendeeId: string; eventId: number; attendee: string; email: string; type: string; quantity: number; price: number; status: "Active" | "Checked in" | "Checked out" | "Transferred" | "Revoked" | "Refunded"; payment: "Preview booking" | "Payment verified"; paymentMode: "demo" | "zcash-testnet"; paymentTxid?: string | null; paymentAmountZat?: string | null; entryCredential?: string; date: string }

const EVENT_COLUMNS = "id, organizer_id, title, category, city, venue, event_date, event_time, price, sold, capacity, image, description, featured"

async function fetchPublicEvents(): Promise<EventItem[]> {
  const { data, error } = await createClient().from("events").select(EVENT_COLUMNS).order("created_at", { ascending: false })
  if (error) throw error

  return (data ?? []).map(event => ({
    id: Number(event.id),
    organizerId: event.organizer_id,
    title: event.title,
    category: event.category,
    city: event.city,
    venue: event.venue,
    date: event.event_date,
    time: event.event_time,
    price: event.price,
    sold: event.sold,
    capacity: event.capacity,
    image: event.image,
    description: event.description,
    featured: event.featured,
    preview: false,
  }))
}

async function fetchAccessibleTickets(): Promise<TicketItem[]> {
  const { data, error } = await createClient().from("tickets").select("id, event_id, attendee_id, attendee_name, attendee_email, quantity, total_amount, ticket_reference, status, payment_status, payment_mode, payment_txid, payment_amount_zat").order("created_at", { ascending: false })
  if (error) throw error
  return (data ?? []).map(ticket => ({
    id: ticket.ticket_reference,
    recordId: ticket.id,
    attendeeId: ticket.attendee_id,
    eventId: Number(ticket.event_id),
    attendee: ticket.attendee_name,
    email: ticket.attendee_email,
    type: "General pass",
    quantity: ticket.quantity,
    price: Number(ticket.total_amount),
    status: ticket.status as TicketItem["status"],
    payment: ticket.payment_mode === "zcash-testnet" ? "Payment verified" : "Preview booking",
    paymentMode: ticket.payment_mode === "zcash-testnet" ? "zcash-testnet" : "demo",
    paymentTxid: ticket.payment_txid,
    paymentAmountZat: ticket.payment_amount_zat == null ? null : String(ticket.payment_amount_zat),
    date: "",
  }))
}

